// Parse input from webhook
const body = $input.first().json.body || $input.first().json;

const city = body.city || body.stadt || 'Berlin';
const roomType = body.room_type || body.zimmertyp || 'Doppelzimmer';
const checkin = body.checkin || body.checkin_date || new Date().toISOString().split('T')[0];
const nights = parseInt(body.nights || body.naechte || 1);
const hotelId = body.hotel_id || 'unknown';

// Calculate checkout date
const checkinDate = new Date(checkin);
const checkoutDate = new Date(checkinDate);
checkoutDate.setDate(checkoutDate.getDate() + nights);
const checkout = checkoutDate.toISOString().split('T')[0];

// Determine day of week (0=Sun, 5=Fri, 6=Sat)
const dayOfWeek = checkinDate.getDay();
const isWeekend = dayOfWeek === 5 || dayOfWeek === 6; // Fri or Sat
const dayNames = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];

// Determine season
const month = checkinDate.getMonth() + 1; // 1-12
let season;
if (month >= 6 && month <= 8) season = 'Hochsaison (Sommer)';
else if (month >= 12 || month <= 2) season = 'Nebensaison (Winter)';
else season = 'Schulter-Saison';

// Lead time in days
const today = new Date();
const leadTimeDays = Math.max(0, Math.round((checkinDate - today) / (1000*60*60*24)));

return [{
  json: {
    city,
    roomType,
    checkin,
    checkout,
    nights,
    hotelId,
    dayOfWeek: dayNames[dayOfWeek],
    isWeekend,
    season,
    leadTimeDays
  }
}];

// Extract prices from Booking.com HTML
// Falls blocked → use realistic mock data for German cities

const inputData = $('Parse Input').first().json;
const city = (inputData.city || 'Berlin').toLowerCase();
const roomType = (inputData.roomType || 'Doppelzimmer').toLowerCase();

// Try to parse real prices from HTML
let prices = [];
try {
  const html = $input.first().json || '';
  if (typeof html === 'string' && html.length > 1000) {
    // Look for price patterns in Booking.com HTML
    const priceRegex = /€\s*(\d+)/g;
    const altRegex = /(\d{2,3})\s*€/g;
    let match;
    while ((match = priceRegex.exec(html)) !== null) {
      const p = parseInt(match[1]);
      if (p >= 30 && p <= 800) prices.push(p);
    }
    while ((match = altRegex.exec(html)) !== null) {
      const p = parseInt(match[1]);
      if (p >= 30 && p <= 800) prices.push(p);
    }
    // Deduplicate and limit
    prices = [...new Set(prices)].slice(0, 20);
  }
} catch(e) {
  prices = [];
}

// Fallback: realistic mock prices for German cities
if (prices.length < 3) {
  const mockPrices = {
    berlin:    { single: [65,75,85,90,95,110,125], double: [85,95,105,120,135,150,165,180], suite: [180,200,230,260,300] },
    münchen:   { single: [80,90,100,115,125,140],   double: [105,120,135,150,170,190,210,220], suite: [220,250,290,340] },
    munich:    { single: [80,90,100,115,125,140],   double: [105,120,135,150,170,190,210,220], suite: [220,250,290,340] },
    hamburg:   { single: [70,80,90,100,115],        double: [90,105,115,130,145,160,175], suite: [175,200,230,260] },
    köln:      { single: [65,75,85,95,110],         double: [85,100,110,125,140,155], suite: [155,180,210,240] },
    cologne:   { single: [65,75,85,95,110],         double: [85,100,110,125,140,155], suite: [155,180,210,240] },
    frankfurt: { single: [75,88,98,110,125,140],    double: [95,110,125,140,160,180,195], suite: [195,220,260,300] },
    dresden:   { single: [55,65,72,80,90],          double: [65,75,85,95,110,120,130], suite: [130,150,170,200] },
    leipzig:   { single: [55,62,70,80,88],          double: [68,78,88,98,110,122], suite: [122,140,165,185] },
    düsseldorf:{ single: [70,82,92,102,115],        double: [88,100,115,130,145,160,172], suite: [172,195,225,255] },
    stuttgart: { single: [72,82,95,108,120],        double: [92,108,122,138,155,170,188], suite: [188,215,248,280] },
    default:   { single: [60,70,80,90,100],         double: [80,90,100,115,130,145], suite: [145,170,200,230] }
  };

  const cityKey = Object.keys(mockPrices).find(k => city.includes(k)) || 'default';
  let typeKey = 'double';
  if (roomType.includes('single') || roomType.includes('einzel')) typeKey = 'single';
  else if (roomType.includes('suite')) typeKey = 'suite';

  prices = mockPrices[cityKey][typeKey];
}

// Calculate stats
const sorted = [...prices].sort((a,b) => a - b);
const min = sorted[0];
const max = sorted[sorted.length - 1];
const avg = Math.round(prices.reduce((s,p) => s+p, 0) / prices.length);
const median = sorted[Math.floor(sorted.length / 2)];

return [{
  json: {
    ...inputData,
    competitor_prices: prices,
    competitor_min: min,
    competitor_max: max,
    competitor_avg: avg,
    competitor_median: median,
    data_source: prices.length >= 3 ? 'booking_com' : 'mock_data'
  }
}];

