// Parse Claude's response and build final output
const claudeResponse = $input.first().json;
const pricingData = $('Parse Competitor Prices').first().json;

let aiResult = {
  recommended_price: Math.round(pricingData.competitor_avg * 0.92),
  min_price: pricingData.competitor_min,
  max_price: pricingData.competitor_max,
  confidence: 'mittel',
  reasoning: 'Preis basiert auf Marktanalyse. Claude-Analyse nicht verfügbar.'
};

try {
  const content = claudeResponse.content?.[0]?.text || '';
  // Extract JSON from response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    aiResult = {
      recommended_price: parseInt(parsed.recommended_price) || aiResult.recommended_price,
      min_price: parseInt(parsed.min_price) || pricingData.competitor_min,
      max_price: parseInt(parsed.max_price) || pricingData.competitor_max,
      confidence: parsed.confidence || 'mittel',
      reasoning: parsed.reasoning || aiResult.reasoning
    };
  }
} catch(e) {
  // Use fallback values
}

return [{
  json: {
    recommended_price: aiResult.recommended_price,
    min_price: aiResult.min_price,
    max_price: aiResult.max_price,
    confidence: aiResult.confidence,
    reasoning: aiResult.reasoning,
    competitor_avg: pricingData.competitor_avg,
    competitor_min: pricingData.competitor_min,
    competitor_max: pricingData.competitor_max,
    city: pricingData.city,
    room_type: pricingData.roomType,
    checkin: pricingData.checkin,
    nights: pricingData.nights,
    season: pricingData.season,
    day_of_week: pricingData.dayOfWeek,
    is_weekend: pricingData.isWeekend,
    lead_time_days: pricingData.leadTimeDays,
    data_source: pricingData.data_source,
    generated_at: new Date().toISOString()
  }
}];
